from datetime import datetime

def parse_dt(s):
    if not s: return datetime.min
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        try:
            return datetime.strptime(s,'%Y-%m-%dT%H:%M:%S')
        except Exception:
            return datetime.min

# Fetch all sent payment requests (no status filter)
all_reqs=[]
page_limit=20
page_index=0
while True:
    resp=apis.venmo.show_sent_payment_requests(access_token=venmo_token,page_index=page_index,page_limit=page_limit)
    if isinstance(resp, dict) and 'failure' in resp:
        raise RuntimeError(resp)
    page = resp if isinstance(resp, list) else resp.get('success',[])
    print('page_index',page_index,'count',len(page))
    if not page:
        break
    all_reqs.extend(page)
    page_index+=1
print('total sent payment requests',len(all_reqs))

# Filter for receiver Brandon
brandon_reqs=[]
for r in all_reqs:
    recv=r.get('receiver',{}) or {}
    name=(recv.get('name') or '')
    email=(recv.get('email') or '')
    if 'brandon' in name.lower() or 'brandon' in email.lower():
        brandon_reqs.append(r)
print('brandon-related sent requests',len(brandon_reqs))

# Pick latest by created_at
brandon_sorted=sorted(brandon_reqs, key=lambda r: parse_dt(r.get('created_at')))
print('latest brandon sent request:')
if not brandon_sorted:
    print('none')
else:
    latest=brandon_sorted[-1]
    print('payment_request_id',latest.get('payment_request_id'))
    print('amount',latest.get('amount'))
    print('receiver',latest.get('receiver'))
    print('status fields approved_at',latest.get('approved_at'),'denied_at',latest.get('denied_at'))
    print('created_at',latest.get('created_at'))

